        $courses = DB::table('courses')->pluck('id', 'title');

        $batch = [];
        $now   = now();

        foreach ($data as [$courseTitle, $content, $sortOrder]) {
            $courseId = $courses[$courseTitle] ?? null;
            if (!$courseId) continue;

            $batch[] = [
                'course_id'  => $courseId,
                'content'    => $content,
                'sort_order' => $sortOrder,
                'created_at' => $now,
                'updated_at' => $now,
            ];

            if (count($batch) === 500) {
                DB::table('learning_outcomes')->insertOrIgnore($batch);
                $batch = [];
            }
        }

        if (!empty($batch)) {
            DB::table('learning_outcomes')->insertOrIgnore($batch);
        }
